import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易闡真 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易闡真 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"classics/chanzhen/005.md","filePath":"classics/chanzhen/005.md"}'),s={name:"classics/chanzhen/005.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：山下有險，險而止，蒙。蒙亨，以亨行時中也。匪我求童蒙，童蒙求我，志應也。初筮告，以剛中也。再三瀆，瀆則不告，瀆蒙也。蒙以養正，聖功也。</p></blockquote><h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>初六：發矇，利用刑人，用說桎梏，以往吝。</p><p>九二：包蒙吉。納婦吉，子克家。</p><p>六三：勿用取女。見金夫，不有躬，無攸利。</p><p>六四：困蒙，吝。</p><p>六五：童蒙，吉。</p><p>上九：擊蒙，不利為寇，利禦寇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山下出泉，蒙。君子以果行育德。</p><p>蒙者，無識無知，修養之義。上艮山，下坎水，坎言泉而不言水者，山下之泉即是水。山下出泉，泉得山養，為有本之水，源遠流長，通行無阻，蒙之象也。</p><p>君子有見於此，知修道者欲行德於外，先須養德於內，若不養而即行，則行而無本，中無主宰，反傷其德。以是效泉之出山，無阻而果行；法山之養泉，敦厚而育德也。坎中一陽，系天一所生，乃生物之祖氣，所謂天德者是也。此德隱於後天之中，一切常人，順其後天，棄其先天，多不知育養修持，漸次消耗，自傷性命。若有醒悟者，截然放下，育於內而行於外，育以濟行，行以驗育，內外兼修，育固養，行亦養，可以復全天德，不為後天陰氣所傷矣。但育德須要無一德之不育，果行須要無一行之不果。育德須要育到如山之不動不搖，方是育之至；果行須要果到如泉之晝夜流通，方是果之至。行果德育，儘性了命，渾然天理，不識不知，順帝之則，此蒙之所以貴也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>瀆，音獨。說，音脫。桎，音質。梏，古毒反。</p><p>蒙者，昏昧無知之義。卦體上艮，二陰進於一陽之下；下坎，一陽陷於二陰之中，皆有陰傷其陽之象，故謂蒙。又卦德險在止中，有險而能止，兼有止蒙之義。此運陰符下手之卦，承上坤卦而來。坤者，行順道也。運陰符者，運其不順之陰，而歸於順也。</p><p>人自先天陽極，後天陰生，元神昧而識神用事，陷真認假，誤用聰明，巧智百出，外雖明而內實暗，此蒙之所由來也。一入於蒙，性亂命搖，一日千生萬死，莫知底止，險之極矣。若知有險而能止之，黜聰毀智，如愚如訥，外雖無知，內實有知，由假蒙而歸真蒙，是蒙中反有亨道矣。</p><p>蒙之亨者，莫過於童。蒙童之蒙，不識不知，順帝之則，寂然不動，感而遂通，一舉一動，皆從本性中流出，儼然聖賢身分，天人面目。行蒙道者，必歸於童之蒙，方是返本還元之蒙。然此返本還元之蒙，匪我求童蒙，童蒙求我也。</p><p>匪我求童蒙者，非由勉強，不著於色也。童蒙求我者，出於自然，不落於空也。不著於色，不落於空，非色非空，既非求真，又不除假，常靜常應，常應常靜，不蒙而似蒙，蒙而實不蒙，外物不得而入，內念不得而生，不求真而真即在是。但此非色非空之道，有養蒙發矇二法，不可不知。當其陰陽混成，天真未傷，客氣未入，蒙屬於真，如初筮著策未分之時，必先告命，須當虛靜誠敬，以行無為之道。及其陰陽已判，天真有虧，客氣潛入，蒙歸於假，如蓍策再三瀆亂之時，不待告命，可以變化裁製，以行有為之道。</p><p>無為之道，養真蒙也；有為之道，化假蒙也。養真化假，有為無為，隨時而用，不失其正。或自有為而歸無為，或自無為而成有為，總以至善無惡，渾然天理，還元返本，歸於童蒙為極功。行蒙道者，可不以正哉!</p><p>初六，在蒙之初，人心方起，急須嚴加剋制，如利用刑人也。若姑息養奸，縱性為惡，如用說桎梏以往，漸入於下愚不移之地，而莫可救止，取吝必矣。此貴防陰於蒙之初也。</p><p>九二，剛而能柔，借陰養陽，是包蒙也。蒙在包中，外暗內明，不但陽氣不傷，而且陽氣增長，如納婦之吉，而子自克家。此能養陽於蒙之時也。</p><p>六三，陰柔不中不正，恣情縱欲，故勿用取女。勿用者，以其人心用事，貪財好色，如淫奔之女，見金夫不有躬，未得於人，早失其己，其無所利，可知此蒙，而又滋其蒙也。</p><p>六四，性質本愚，又與小人為伍，不知親近高明之士，以擴充其識見，終困於蒙而不得出，豈只取吝而已乎?此蒙而不知其蒙也。</p><p>六五，於止知其所止，以無能而順有能，借剛濟柔，雖蒙不蒙，正童蒙，不識不知，順帝之則之吉道。此蒙而自知其蒙也。</p><p>上九，剛而居於蒙之極，是能懲忿窒欲，猛力以退客氣，如擊蒙也。</p><p>退陰之道，不利於人心而為寇，利於道心而禦寇。去人心，振道心，陰氣退盡，陽氣純全，復見本來面目，此蒙而終不能蒙也。</p><p>觀於六爻之蒙，真假大別，真者用而假者去，養之退之，皆能不失其正，陰符之道盡矣。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
